// Gemma image-only equations. BF16 activation boundaries, FP32 reductions.
#include <cuda_bf16.h>
#include <math.h>
__device__ float bf(float x){return __bfloat162float(__float2bfloat16(x));}
extern "C" __global__ void gv_unpack(const unsigned char*p,const __nv_bfloat16*s,__nv_bfloat16*y,int rows,int cols){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=rows*cols)return;int row=i/cols,col=i%cols,pc=(cols+127)/128*128;int index=row*pc+col;int q=((p[index/2]>>((index%2)*4))&15)-8;y[i]=__float2bfloat16(q*__bfloat162float(s[row*((cols+127)/128)+col/128]));}
extern "C" __global__ void gv_rms(const __nv_bfloat16*x,const __nv_bfloat16*w,__nv_bfloat16*y,int cols){int r=blockIdx.x;__shared__ float sums[256];float sum=0;for(int j=threadIdx.x;j<cols;j+=256){float v=__bfloat162float(x[r*cols+j]);sum+=v*v;}sums[threadIdx.x]=sum;__syncthreads();for(int d=128;d;d/=2){if(threadIdx.x<d)sums[threadIdx.x]+=sums[threadIdx.x+d];__syncthreads();}float inv=powf(sums[0]/cols+1e-6f,-.5f);for(int j=threadIdx.x;j<cols;j+=256)y[r*cols+j]=__float2bfloat16(__bfloat162float(x[r*cols+j])*inv*(w?__bfloat162float(w[j]):1.f));}
extern "C" __global__ void gv_pixels(const __nv_bfloat16*x,__nv_bfloat16*y,int count){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<count)y[i]=__float2bfloat16(2.f*bf(__bfloat162float(x[i])-.5f));}
extern "C" __global__ void gv_position(__nv_bfloat16*x,const __nv_bfloat16*p,int n,int h,int gw,int extent){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n*h)return;int t=i/h,c=i%h;float pos=bf(__bfloat162float(p[(t%gw)*h+c])+__bfloat162float(p[(extent+t/gw)*h+c]));x[i]=__float2bfloat16(__bfloat162float(x[i])+pos);}
extern "C" __global__ void gv_rope(__nv_bfloat16*x,int n,int heads,int dim,int gw){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n*heads*(dim/2))return;int d=i%(dim/2),head=i/(dim/2)%heads,t=i/(dim/2)/heads;int part=d/(dim/4),f=d%(dim/4),coord=part==0?t%gw:t/gw;float angle=coord*powf(100.f,-float(2*f)/(dim/2));float c=bf(cosf(angle)),s=bf(sinf(angle));int index=(t*heads+head)*dim+part*(dim/2)+f;float a=__bfloat162float(x[index]),b=__bfloat162float(x[index+dim/4]);x[index]=__float2bfloat16(bf(a*c)-bf(b*s));x[index+dim/4]=__float2bfloat16(bf(b*c)+bf(a*s));}
extern "C" __global__ void gv_gate(__nv_bfloat16*g,const __nv_bfloat16*u,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;float x=__bfloat162float(g[i]);float gelu=bf(.5f*x*(1.f+tanhf(.7978845608028654f*(x+.044715f*x*x*x))));g[i]=__float2bfloat16(gelu*__bfloat162float(u[i]));}
extern "C" __global__ void gv_add(__nv_bfloat16*x,const __nv_bfloat16*y,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)x[i]=__float2bfloat16(__bfloat162float(x[i])+__bfloat162float(y[i]));}
extern "C" __global__ void gv_pool(const __nv_bfloat16*x,const __nv_bfloat16*bias,const __nv_bfloat16*scale,__nv_bfloat16*y,int n,int h,int gh,int gw){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n*h)return;int t=i/h,c=i%h,px=(t%(gw/3))*3,py=t/(gw/3)*3;float sum=0;for(int dy=0;dy<3;dy++)for(int dx=0;dx<3;dx++)sum+=__bfloat162float(x[((py+dy)*gw+px+dx)*h+c])*(1.f/9.f);float v=bf(sum)*sqrtf(float(h));if(bias)v=(v-__bfloat162float(bias[c]))*__bfloat162float(scale[c]);y[i]=__float2bfloat16(v);}
extern "C" __global__ void gv_pad(const __nv_bfloat16*x,__nv_bfloat16*y,int rows,int dim,int reverse){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=rows*96)return;int row=i/96,c=i%96;if(reverse){if(c<dim)y[row*dim+c]=x[i];}else y[i]=c<dim?x[row*dim+c]:__float2bfloat16(0.f);}

extern "C" __global__ void gv_assemble(__nv_bfloat16*x,const __nv_bfloat16*features,const int*image_rows,int total,int h,float scale){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=total)return;int image=image_rows[i/h];x[i]=image>=0?features[image*h+i%h]:__float2bfloat16(__bfloat162float(x[i])*scale);}
